'use strict';
let globalData,globalSection='connection',usageSection='summary',ledgerOffset=0,usageTrend='calls';
const globalDrafts=new Map();
const ledgerFilters={q:'',provider:'',account:'',failed:false,day:'',model:'',route:'',purpose:'',computer:''};
function groupGlobalFields(root){
 for(const label of root.querySelectorAll('.form-grid > label[for]')){
  const control=label.nextElementSibling;
  if(!control||!(control.id===label.htmlFor||control.querySelector('select')?.id===label.htmlFor))continue;
  const group=document.createElement('div');group.className='form-field';label.before(group);group.append(label,control);
  while(group.nextElementSibling?.matches('p.form-hint,p.inline-error'))group.append(group.nextElementSibling);
 }
}
const globalSections={connection:'连接与显示',tools:'搜索与图像',privacy:'隐私与脱敏',telemetry:'请求记录与遥测',backup:'备份与同步'};
const usageSections={summary:'调用汇总',ledger:'请求账本',quotas:'余额与订阅额度',routing:'路由记录'};
let quotaNoticeSequence=0,quotaNotices=[];
function quotaNoticeText(raw){const a=normalizeModel(raw);return `${a.name||a.provider}${a.user?' · '+a.user:''}：${a.kind==='expires'?`${a.credits||0} 次重置即将到期`:a.kind==='renews'?`${a.window} 即将重置，已使用 ${Number(a.used||0).toFixed(1)}%`:a.balance?`当前余额 ${a.balance}`:`${a.window||'额度'} 已使用 ${Number(a.used||0).toFixed(1)}%`}${a.resetsAt?' · '+dateText(a.resetsAt):''}`;}
async function refreshQuotaNotices(){if(document.hidden)return;try{const r=await api('subscriptions/alerts?after='+quotaNoticeSequence);quotaNoticeSequence=r.sequence;for(const a of r.alerts||[])quotaNotices.push(a);quotaNotices=quotaNotices.slice(-60);const b=$('#quota-notices');if(b){b.textContent=`提醒${quotaNotices.length?' · '+quotaNotices.length:''}`;b.hidden=!quotaNotices.length;}if(r.alerts?.length)message(quotaNoticeText(r.alerts.at(-1).alert));}catch(e){const b=$('#quota-notices');if(b){b.title='提醒读取失败：'+e.message;}}}
document.addEventListener('DOMContentLoaded',()=>{const b=document.createElement('button');b.id='quota-notices';b.type='button';b.hidden=true;b.onclick=()=>{editor={type:'read-only'};$('#editor-title').textContent='供应商额度提醒';$('#fields').innerHTML=`<div class="panel">${quotaNotices.slice().reverse().map(n=>`<div class="row"><div class="text"><strong>${escape(quotaNoticeText(n.alert))}</strong><p class="caption">${escape(dateText(n.at))}</p></div></div>`).join('')}</div>`;showEditor();$('#save').hidden=true;};$('.toolbar-actions')?.prepend(b);refreshQuotaNotices();setInterval(refreshQuotaNotices,30000);});
const globalNumber=(value,digits=0)=>Number(value||0).toLocaleString('zh-CN',{maximumFractionDigits:digits});
function localLedgerDay(value){const d=new Date(value);return Number.isNaN(d.getTime())?'':`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function exchangeRateNote(){const fx=globalData.fx||{};if(!(fx.rate>0))return '人民币汇率暂不可用，费用继续按 USD 显示。';return `人民币换算参考：1 USD ≈ ${Number(fx.rate).toFixed(4)} CNY${fx.at?` · 获取于 ${escape(dateText(fx.at))}`:''}。${fx.stale?'当前使用缓存或离线参考值。':''}`;}
function globalCost(value){const c=globalData?.settings.currency,r=globalData?.fx?.rate;return `${c==='cny'&&r>0?'¥':'$'}${Number((value||0)*(c==='cny'&&r>0?r:1)).toFixed(3)}`;}
function pageSegments(items,current){return `<div class="segments page-segments" role="tablist">${Object.entries(items).map(([id,name])=>`<button type="button" role="tab" data-global-section="${id}" aria-selected="${id===current}" aria-pressed="${id===current}">${name}</button>`).join('')}</div>`;}
function sectionHead(title,note){return `<div class="section-head"><div><h2>${title}</h2><p>${note}</p></div></div>`;}
function settingPanel(title,note,body){return `<section class="settings-panel panel">${sectionHead(title,note)}<div class="form-grid">${body}</div></section>`;}
function settingsForm(body){return `<form id="global-form">${body}<div class="page-save-bar"><span id="global-save-status" role="status">修改后保存生效</span><div class="actions">${button('取消修改','','','').replace('data-action=""','data-global="cancel-settings"')}<button type="submit" class="primary">保存设置</button></div></div></form>`;}
function modelChoices(models,current){const choices=[['','自动选择'],['off','关闭'],...(models||[]).map(m=>[m.id,m.name||m.id])];if(current&&!choices.some(([id])=>id===current))choices.push([current,current+'（保留当前设置，未出现在候选中）']);return choices;}
function imageChoice(kind,label,current){const models=kind==='vision'?globalData.visionModels:globalData.drawingModels,unused=globalData[kind==='vision'?'visionUnused':'imageGenUnused'],automatic=globalData[kind==='vision'?'autoVision':'autoDrawer'];return selectField(kind,label,modelChoices(models,current),current)+'<p class="'+(unused?'inline-error':'form-hint')+'">'+(unused?'当前设置已失效，运行时将自动选择；原值保留。':'')+'自动候选：'+escape(automatic||'无可用模型')+'</p>';}

function compactionSettings(s){return settingPanel('对话压缩','模型和供应商独立阈值优先；使用完整窗口仍保留回复 Token 与安全余量。',checkField('fullContext','使用模型完整窗口',s.fullContext)+integerField('compactAt','全局提前压缩阈值（Token）',s.compactAt||0,0,null,'0 使用默认 272K；只对实际窗口更大的模型生效'));}
function connectionSettings(){const s=globalData.settings;return settingsForm(compactionSettings(s)+settingPanel('连接','供鲸桥发往供应商的请求使用。供应商和账号的独立代理优先于此处。',proxyFields(s.proxy||''))+settingPanel('模型名称与费用显示','只改变显示名称和估算费用的币种，不改变模型 ID 或供应商账单。',selectField('currency','估算费用币种',[['usd','美元 USD'],['cny','人民币 CNY']],s.currency||'usd')+checkField('chineseUnits','大数使用万、亿',s.chineseUnits)+checkField('plainNames','模型名称不附加供应商',s.plainNames)+checkField('plainOwnNames','自定义模型名称保持原样',s.plainOwnNames)+checkField('memberModel','路由回复报告实际成员模型',s.memberModel))+`<p class="caption">${exchangeRateNote()}原始用量费用以 USD 保存。</p>`)+uniformPricePanel();}
function searchRows(){return (globalData.searchVendors||[]).map(raw=>{const v=normalizeModel(raw),a=(globalData.searches||[]).find(x=>x.vendor===v.id);return `<div class="row"><div class="text"><h3>${escape(v.name)}</h3><p class="caption">${a?`${a.ready?'已配置':'配置不完整'} · ${escape(a.url||v.base||'')} · ${escape(a.keyMasked||'无需密钥')}`:'尚未配置'} ${externalLink(v.keysURL||v.keysUrl,'获取密钥')}</p></div><div class="actions"><button type="button" data-global="edit-search" data-id="${v.id}">${a?'编辑':'添加'}</button>${a?`<button type="button" data-global="show-search" data-id="${v.id}">显示密钥</button><button type="button" data-global="copy-search" data-id="${v.id}">复制密钥</button><button type="button" class="danger" data-global="remove-search" data-id="${v.id}">移除</button>`:''}</div></div>`;}).join('');}
function searcherField(){const selected=globalData.settings.searcher||'',choices=[['','自动选择'],...(globalData.searchers||[]).flatMap(c=>[[c.id,c.name+(c.manualOnly?' · 仅手动':'')],...(c.models||[]).map(m=>[m.id,c.name+' · '+m.name])]),['manual','手动指定 / 保留当前值']],choice=choices.some(([id])=>id===selected)?selected:'manual',why=({gone:'供应商不存在',off:'供应商已停用或未登录',cant:'供应商不支持网页搜索',nomodel:'未找到可用搜索模型'})[globalData.searcherUnused];return selectField('searcherChoice','选择搜索供应商或模型',choices,choice)+field('searcher','搜索供应商或模型 ID',selected,'text','留空自动选择；可手写供应商 ID 或 供应商/模型')+'<p class="'+(why?'inline-error':'form-hint')+'">'+(why?'当前设置未被使用：'+escape(why)+'。':'')+'当前模型搜索：'+escape(globalData.searcher||'无可用模型')+'；自动候选：'+escape(globalData.autoSearcher||'无可用模型')+'。'+((globalData.searches||[]).some(a=>a.ready)?'已配置的搜索 API 可补充检索。':'')+'</p>';}
function toolsSettings(){const s=globalData.settings;return settingsForm(settingPanel('网页搜索','模型无法原生搜索时，由选定模型或搜索 API 补充检索。',searcherField()+selectField('searchFirst','优先搜索来源',[['','供应商模型优先'],['api','搜索 API 优先']],s.searchFirst||''))+settingPanel('图像处理','为不能看图的模型描述图片；图像生成默认模型也用于未指定模型的生成请求。',imageChoice('vision','图片理解模型',s.vision||'')+imageChoice('imageGen','图像生成默认模型',s.imageGen||'')))+sectionHead('搜索 API','密钥只在主动显示时返回；清空编辑框会保留已有密钥。')+`<section class="panel">${searchRows()}</section><section class="panel global-form-panel" id="search-editor" hidden></section>`;}
function ruleRow(r={}){return `<div class="redact-rule-row"><label>占位符名称<input data-rule="kind" value="${escape(r.kind||'CUSTOM')}" placeholder="CUSTOM"></label><label>匹配方式<select data-rule="mode"><option value="prefix" ${!r.regex?'selected':''}>前缀</option><option value="regex" ${r.regex?'selected':''}>正则表达式</option></select></label><label>匹配内容<input data-rule="value" value="${escape(r.regex||r.prefix||'')}" placeholder="例如 oc_sk_"></label><button type="button" data-global="remove-rule" aria-label="移除规则">移除</button></div>`;}
function privacySettings(){const s=globalData.settings;return settingsForm(settingPanel('发送前脱敏','敏感值替换为占位符发送，供应商回复中的占位符在本机恢复。可信本地供应商可单独豁免。',checkField('redact','保护 API 密钥、令牌、私钥和密码',s.redact)+checkField('redactPersonal','保护邮箱、电话和身份信息',s.redactPersonal)+text('redactWords','额外保护的词语',(s.redactWords||[]).join('\n'),'每行一个词语'))+`<section class="panel global-form-panel">${sectionHead('自定义敏感值规则','补充内置规则未覆盖的密钥前缀或 RE2 正则表达式。')}<div id="redact-rules">${(s.redactRules||[]).map(ruleRow).join('')}</div><button type="button" data-global="add-rule">添加规则</button></section>`);}
function telemetrySettings(){const s=globalData.settings,o=s.otel||{};return settingsForm(settingPanel('额度提醒','提醒不会改变账号请求分配，也不会自动消耗重置或付费额度。',integerField('usageAlert','额度已用百分比提醒',s.usageAlert||0,0,100,'0 关闭')+field('balanceAlert','余额低于此值提醒',s.balanceAlert||0,'number','0 关闭，使用供应商余额本身的单位')+integerField('resetReminder','到期前提醒（小时）',s.resetReminder||0,0,168,'0 关闭，最多提前 168 小时'))+settingPanel('S3 请求归档','保存请求与响应，内置敏感值先被遮盖。归档文件不由备份口令加密，需先配置 S3 同步。',checkField('requestArchive','归档供应商请求和响应',s.requestArchive)+integerField('requestArchiveMaxMB','每份请求体上限（MiB）',s.requestArchiveMaxMB||32,1,1024))+settingPanel('OTLP / HTTP 遥测','导出通过鲸桥的请求。开启正文会把脱敏后的对话内容发送到你配置的服务。',checkField('otel-enabled','启用遥测导出',o.enabled)+field('otel-endpoint','服务地址',o.endpoint||'','url','https://服务地址/api/public/otel')+checkField('otel-metrics','导出指标',o.metrics)+checkField('otel-bodies','导出请求与响应正文',o.bodies)+checkField('otel-bodiesWhole','导出完整正文',o.bodiesWhole)+text('otel-headers','认证 Header 编辑','','每行 名称=值；留空保留；名称= 删除')+`<p class="form-hint">已保存 Header：${escape((o.headerNames||[]).join('、')||'无')}。已有值不会自动显示。</p>`));}
function syncPanel(){const s=globalData.sync||{};return `<section class="panel global-form-panel">${sectionHead('WebDAV / S3 同步','同步供应商、搜索服务、路由组和相关设置；包含恢复前备份和冲突记录。')}<p class="caption">${s.on?'已开启':'未开启'}${s.last?` · 最近同步 ${escape(dateText(s.last))}`:''}${s.error?` · ${escape(s.error)}`:''}</p>${s.notice?`<div class="notice"><p>同步替换了配置：${escape([...(s.notice.here||[]),...(s.notice.there||[])].join('、'))}</p>${s.notice.saved?`<p class="caption">原配置保留于 ${escape(s.notice.saved)}</p>`:''}<button type="button" data-global="sync-dismiss">已阅读同步变更</button></div>`:''}<form id="sync-form"><div class="form-grid">${field('url','服务器地址',s.url||'','text','https://WebDAV/folder 或 s3://bucket/prefix')+field('user','用户名 / S3 Access Key',s.user||'')+field('password','密码 / S3 Secret Key','','password','留空保留已保存密码')+field('passphrase','同步加密口令','','password','已有同步留空保留')+field('endpoint','S3 兼容端点',s.endpoint||'','text','AWS 可留空')+field('region','S3 区域',s.region||'','text','如 auto 或 us-east-1')+checkField('pathStyle','S3 使用路径式地址',s.pathStyle)+checkField('keys','同步供应商与搜索服务密钥',s.keys)+checkField('usage','同步用量记录',s.usage)+selectField('autoEvery','自动同步间隔',[['-1','仅手动'],['3','3 分钟'],['15','15 分钟'],['30','30 分钟'],['60','60 分钟']],String(s.on?s.auto || -1:3))}</div><div class="actions-bar"><button class="primary" type="submit">保存并同步</button>${s.on?`<button type="button" data-global="sync-now">现在同步</button><button type="button" data-global="sync-restore">使用服务器配置</button><button type="button" data-global="sync-undo">撤销最近恢复</button><button type="button" data-global="sync-off">关闭同步</button>`:''}</div></form></section>`;}
function backupSettings(){return `<section class="panel global-form-panel">${sectionHead('加密备份','备份供应商、密钥、模型设置、路由组与搜索配置。订阅登录凭据不包含在备份中，恢复后需重新登录。')}<form id="backup-export-form"><div class="form-grid">${field('pass','备份加密口令','','password')+checkField('keys','包含供应商和搜索 API 密钥',true)}</div><div class="actions-bar"><button class="primary" type="submit">导出加密备份</button></div></form></section><section class="panel global-form-panel">${sectionHead('选择性恢复','恢复所选内容；已有供应商按 ID 替换，其他内容保留。')}<form id="backup-import-form"><div class="form-grid"><label for="backup-file">备份文件</label><input id="backup-file" name="file" type="file" accept=".magpie-backup" required>${field('pass','解密口令','','password')+checkField('providers','恢复供应商、模型、路由和搜索服务',true)+checkField('settings','恢复相关设置',true)}</div><div class="actions-bar"><button type="submit">读取并恢复</button></div></form></section>${syncPanel()}`;}
function usageChart(points){if(!points?.length)return '';const label=({calls:'请求数量',tokens:'输入、输出与缓存 Token',cost:'估算费用'})[usageTrend],amount=p=>usageTrend==='cost'?Number(p.cost||0):usageTrend==='tokens'?Number(p.input||0)+Number(p.output||0)+Number(p.cache_read||0)+Number(p.cache_write||0):Number(p.calls||0),display=v=>usageTrend==='cost'?globalCost(v):globalNumber(v),max=Math.max(...points.map(amount),1);return '<section class="panel usage-trend-panel">'+sectionHead('调用趋势','按所选周期展示'+label+'的变化。')+'<label>趋势指标<select id="usage-trend">'+[['calls','请求数量'],['tokens','Token 数量'],['cost','估算费用']].map(([id,name])=>'<option value="'+id+'" '+(usageTrend===id?'selected':'')+'>'+name+'</option>').join('')+'</select></label><div class="usage-chart" role="img" aria-label="'+label+'趋势">'+points.map(p=>'<div class="usage-bar-item" title="'+escape(p.label||dateText(p.time))+'：'+escape(display(amount(p)))+'"><span>'+escape(display(amount(p)))+'</span><progress max="'+max+'" value="'+amount(p)+'"></progress><small>'+escape(p.label||'')+'</small></div>').join('')+'</div></section>';}

function sharesTable(title,rows){return `<section class="panel">${sectionHead(title,`${rows?.length||0} 项`)}${rows?.length?`<div class="table-wrap"><table><thead><tr><th>身份 / 模型</th><th>请求</th><th>失败</th><th>输入 / 输出</th><th>缓存读 / 写</th><th>估算费用</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${escape(r.account||r.providerKeyName||r.model||r.id||'未记录')}</strong><p class="caption">${escape(r.provider||'')}</p></td><td>${short(r.calls)}</td><td>${short(r.errors)}</td><td>${short(r.input)} / ${short(r.output)}</td><td>${short(r.cache_read)} / ${short(r.cache_write)}</td><td>${globalCost(r.cost)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty-inline">这个周期暂无记录。</p>'}</section>`;}
function usageSummary(u){const ttft=u.timed?`${(u.ttft_ms/u.timed/1000).toFixed(2)} s`:'—',speed=u.decode_ms?`${(u.decode_out*1000/u.decode_ms).toFixed(1)} tok/s`:'—';return `<div class="stats">${stat('调用请求',short(u.calls),`${short(u.errors)} 次失败`,'usage')}${stat('输入 / 输出',`${short(u.input)} / ${short(u.output)}`,`缓存读 ${short(u.cache_read)} · 写 ${short(u.cache_write)} · 命中 ${u.input+u.cache_read+u.cache_write>0?(100*u.cache_read/(u.input+u.cache_read+u.cache_write)).toFixed(1)+'%':'—'}`,'models')}${stat('估算费用',globalCost(u.cost),u.unpriced?`${u.unpriced} 次缺少价格`:'以供应商实际账单为准','info')}${stat('首个 Token / 输出速度',`${ttft} / ${speed}`,'仅统计有时间记录的流式回复','info')}</div>${usageChart(u.series)}${sharesTable('按模型',u.models)}${sharesTable('按订阅账号',u.accounts)}${sharesTable('按供应商 API 密钥',u.providerKeys)}`;}
function ledgerQuery(){const q=new URLSearchParams({period,offset:String(ledgerOffset),q:ledgerFilters.q});for(const k of ['provider','account','day','model','route','purpose','computer'])if(ledgerFilters[k])q.set(k,ledgerFilters[k]);if(ledgerFilters.failed)q.set('failed','1');return q.toString();}
function ledgerView(data){const d=normalizeModel(data),rows=(d.rows||[]).map(r=>{r=normalizeModel(r);return {...r,time:r.t||r.time,error:r.err,requestId:r.rid,endpoint:r.ep};});return `<form id="ledger-filter" class="list-toolbar"><input name="q" type="search" aria-label="搜索调用" placeholder="搜索模型、密钥、请求或会话" value="${escape(ledgerFilters.q)}"><select name="provider" aria-label="筛选供应商"><option value="">全部供应商</option>${(d.providers||[]).map(p=>`<option ${p===ledgerFilters.provider?'selected':''}>${escape(p)}</option>`).join('')}</select><input name="account" placeholder="账号" aria-label="筛选账号" value="${escape(ledgerFilters.account)}"><input name="model" placeholder="精确模型 ID" aria-label="筛选模型" value="${escape(ledgerFilters.model)}"><input name="route" type="number" min="1" step="1" placeholder="路由 ID" aria-label="筛选路由" value="${escape(ledgerFilters.route)}"><input name="purpose" placeholder="用途 ID，例如 search / vision" aria-label="筛选用途" value="${escape(ledgerFilters.purpose)}"><input name="computer" list="ledger-computers" placeholder="全部计算机" aria-label="筛选计算机" value="${escape(ledgerFilters.computer)}"><datalist id="ledger-computers"><option value="this">本机</option><option value="others">其他计算机</option></datalist><input name="day" type="date" aria-label="筛选日期" value="${escape(ledgerFilters.day)}"><label class="check-field"><input name="failed" type="checkbox" ${ledgerFilters.failed?'checked':''}><span>只看失败</span></label><button type="submit">筛选</button><a class="button" href="/api/requests/export?${ledgerQuery()}">导出 CSV</a></form><section class="panel"><div class="section-head"><h2>请求账本</h2><span class="caption">${d.total||0} 条 · ${ledgerOffset+1}–${ledgerOffset+rows.length}</span></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>时间 / 请求</th><th>供应商 / 模型</th><th>状态</th><th>输入 / 输出</th><th>费用</th><th>详情</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${escape(dateText(r.time))}<p class="caption">${escape(r.request_id||r.requestId||'')}</p></td><td><strong>${escape(r.model)}</strong><p class="caption">${escape(r.provider)} · ${escape(r.provider_account||r.providerAccount||r.provider_key_name||r.providerKeyName||'')}</p></td><td>${r.status||'—'}${r.error?`<p class="inline-error">${escape(r.error)}</p>`:''}</td><td>${short(r.in||r.input)} / ${short(r.out||r.output)}</td><td>${r.priced?globalCost(r.cost):'价格未知'}</td><td><details><summary>查看</summary><dl class="request-detail"><dt>缓存读 / 写</dt><dd>${short(r.cache_read)} / ${short(r.cache_write)}</dd><dt>首 Token</dt><dd>${r.ttft_ms||0} ms</dd><dt>总耗时</dt><dd>${r.ms||r.millis||0} ms</dd><dt>实际回复模型</dt><dd>${escape(r.served||r.model)}</dd><dt>聚合商实际上游</dt><dd>${escape(r.upstream||'未报告')}</dd><dt>结束原因</dt><dd>${escape(r.stop||'未报告')}</dd><dt>一小时缓存写入</dt><dd>${short(r.cache_write_1h)}</dd><dt>会话</dt><dd>${escape(r.session||'未记录')}</dd><dt>端点</dt><dd>${escape(r.endpoint||'未记录')}</dd><dt>错误类型</dt><dd>${escape(r.errType||r.err_type||'无')}</dd></dl>${r.routeId||r.route_id?`<button type="button" data-global="show-route" data-day="${localLedgerDay(r.time)}" data-id="${r.routeId||r.route_id}">查看路由尝试</button>`:''}${r.archive?`<button type="button" data-global="view-archive" data-id="${escape(r.archive)}">查看归档</button><a href="/api/archive/file?name=${encodeURIComponent(r.archive)}">下载请求归档</a>`:''}</details></td></tr>`).join('')}</tbody></table></div>`:'<p class="empty-inline">没有符合筛选条件的记录。</p>'}<div class="actions-bar"><button type="button" data-global="ledger-prev" ${ledgerOffset===0?'disabled':''}>上一页</button><button type="button" data-global="ledger-next" ${ledgerOffset+rows.length>=(d.total||0)?'disabled':''}>下一页</button></div></section>`;}
function routeNote(c){return [c.barred?'模型已停用':'',c.held?'访问受限':'',c.capped?'达到用量上限 '+c.capped+'%':'',c.noCredits?'不使用付费额度':'',c.turn?'当前轮次':'',c.fallback?'备用候选':'',c.aside?'协议备用':'',c.unlisted?'未列出模型':'',c.fast?'快速模式':'',c.fixed?'固定推理 '+c.fixed:'',c.rest?'暂时休息':'',c.sunk?'限流后排到末尾':''].filter(Boolean).join(' · ')||'可用';}
function routeTable(routes){return routes?.length?'<section class="panel">'+routes.slice().reverse().map(r=>{
const candidates=[...(r.order||[]),...(r.left||[])], rule=r.rule||{}, affinity=r.affinity||{};
return '<details class="route-record"><summary><strong>'+escape(r.model)+'</strong> · '+escape(dateText(r.time))+' · '+(r.done?'HTTP '+(r.status||'—'):'处理中')+(r.error?' · '+escape(r.error):'')+'</summary><dl class="request-detail"><dt>供应商 / 实际模型</dt><dd>'+escape(r.provider)+' / '+escape(r.served||r.model)+'</dd><dt>路由方式</dt><dd>'+escape(r.group?.routing||'供应商默认')+(r.group?' · '+escape(r.group.name||r.group.id):'')+'</dd><dt>首 Token / 总耗时</dt><dd>'+(r.ttft||0)+' / '+(r.ms||0)+' ms</dd><dt>输入与输出总计 / 输出</dt><dd>'+short(r.tokens)+' / '+short(r.out)+'</dd><dt>会话 / 固定账号</dt><dd>'+escape(r.session||'未记录')+' / '+escape(r.pinned||'自动')+'</dd><dt>命中规则</dt><dd>'+escape(rule.name||rule.pattern||rule.kind||rule.id||'无')+'</dd><dt>会话亲和</dt><dd>'+escape(affinity.who||affinity.id||affinity.account||r.group?.affinity||'未固定')+'</dd></dl>'+(r.nested?.length?'<p class="caption">嵌套路径：'+escape(r.nested.map(n=>n.name||n.id||n.group?.name||n.group?.id||'子路由').join(' → '))+'</p>':'')+'<h3>候选与排序</h3><div class="table-wrap"><table><thead><tr><th>顺序</th><th>供应商 / 账号</th><th>模型</th><th>已用额度 / 重置</th><th>状态与原因</th></tr></thead><tbody>'+candidates.map((c,i)=>'<tr><td>'+(i+1)+'</td><td>'+escape(c.name||c.provider)+'<p class="caption">'+escape(c.who||c.id)+'</p></td><td>'+escape(c.model)+'</td><td>'+(c.known?Number(c.used||0).toFixed(1)+'%':'未报告')+'<p class="caption">'+escape((c.renews||[]).map(dateText).join(' · '))+'</p></td><td>'+escape(routeNote(c))+'</td></tr>').join('')+'</tbody></table></div><h3>实际尝试</h3>'+(r.tries?.length?'<div class="table-wrap"><table><thead><tr><th>账号 / 模型</th><th>结果</th><th>首 Token / 总耗时</th><th>排队与恢复</th></tr></thead><tbody>'+r.tries.map(t=>'<tr><td>'+escape(t.id)+'<p class="caption">'+escape(t.served||t.model)+' · '+escape(t.effort||'默认推理')+'</p></td><td>'+(t.done?'HTTP '+(t.status||'—'):'处理中')+'<p class="'+(t.error?'inline-error':'caption')+'">'+escape(t.error||t.fail||t.upstream||'')+'</p></td><td>'+(t.ttft||0)+' / '+(t.ms||0)+' ms</td><td>排队 '+(t.queued||0)+' ms'+(t.again?' · 重试前等待 '+t.again+' ms':'')+(t.reset?'<p class="caption">'+escape(t.reset.who)+' · '+escape(t.reset.text)+'</p>':'')+'</td></tr>').join('')+'</tbody></table></div>':'<p class="empty-inline">尚未尝试。</p>')+'</details>';
}).join('')+'</section>':'<section class="panel"><p class="empty-inline">尚无路由记录。</p></section>';}
function captureGlobalDrafts(){if(tab!=='settings')return;const snapshots=[];for(const f of $('#content').querySelectorAll('form')){if(f.id==='search-edit-form')continue;snapshots.push({id:f.id,dynamic:[...f.querySelectorAll('#redact-rules,#uniform-price-tiers')].map(e=>{const copy=e.cloneNode(true);for(const button of copy.querySelectorAll('button'))button.disabled=false;return {id:e.id,html:copy.innerHTML};}),values:[...f.querySelectorAll('input,select,textarea')].map(i=>({value:i.value,checked:i.checked,type:i.type}))});}if(snapshots.length)globalDrafts.set(globalSection,snapshots);}
function clearGlobalFormDraft(id,section,saved){const remaining=(globalDrafts.get(section)||[]).filter(d=>d.id!==id||JSON.stringify(d)!==JSON.stringify(saved));if(remaining.length)globalDrafts.set(section,remaining);else globalDrafts.delete(section);}
function restoreGlobalDrafts(){for(const d of globalDrafts.get(globalSection)||[]){const f=document.getElementById(d.id);if(!f)continue;for(const block of d.dynamic||[]){const e=f.querySelector('#'+block.id);if(e)e.innerHTML=block.html;}[...f.querySelectorAll('input,select,textarea')].forEach((i,n)=>{const v=d.values[n];if(!v||i.type==='file')return;i.value=v.value;if(i.type==='checkbox')i.checked=v.checked;});}}
document.addEventListener('input',()=>captureGlobalDrafts());
window.renderBridgeGlobalPage=async function(current,epoch){globalData=await api('global');if(epoch!==renderEpoch)return '';if(current==='settings'){const body=({connection:connectionSettings,tools:toolsSettings,privacy:privacySettings,telemetry:telemetrySettings,backup:backupSettings})[globalSection]();return heading('全局设置','管理供应商请求的共同设置、数据和辅助能力。')+pageSegments(globalSections,globalSection)+body;}let html=heading('用量与额度','网关调用与供应商报告分别展示；订阅额度包含鲸桥之外的使用。',`<select id="global-period" aria-label="用量周期">${Object.entries({today:'今天','7d':'近 7 天','30d':'近 30 天',all:'全部'}).map(([v,l])=>`<option value="${v}" ${v===period?'selected':''}>${l}</option>`).join('')}</select>`)+pageSegments(usageSections,usageSection);if(usageSection==='summary')return html+usageSummary(await api(`usage?period=${period}`));if(usageSection==='ledger')return html+ledgerView(await api(`requests?${ledgerQuery()}`));if(usageSection==='routing'){const r=await api('routes/history');return html+`<div class="actions-bar"><button type="button" data-global="live-routes">当前请求</button><select id="route-day" aria-label="路由历史日期"><option value="">选择日期</option>${(r.days||[]).map(d=>`<option value="${escape(d.day||d.Day)}">${escape(d.day||d.Day)}</option>`).join('')}</select></div><div id="route-records">${routeTable((await api('routes')).routes)}</div>`;}return html+`<div class="section-head"><div><h2>供应商余额与订阅额度</h2><p>供应商报告的当前状态，可按账号刷新。</p></div>${button('刷新额度','refresh-quotas')}</div><div class="actions-bar">${button('订阅维护设置','subscription-settings')}${button('额度历史曲线','quota-history')}</div><div id="quota-section" aria-live="polite"></div>`;};
async function globalRerender(){await render();}
function formObject(form){return Object.fromEntries(new FormData(form));}
async function downloadResponse(response,fallback){if(!response.ok)throw new Error(await response.text());const blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=response.headers.get('Content-Disposition')?.match(/filename="([^"]+)"/)?.[1]||fallback;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function globalSave(form){captureGlobalDrafts();const section=globalSection,saved=(globalDrafts.get(section)||[]).find(d=>d.id===form.id),data=formObject(form),s={};for(const input of form.querySelectorAll('[name]')){const k=input.name;if(k.startsWith('otel-')||['proxyMode','proxy','searcherChoice'].includes(k))continue;s[k]=input.type==='checkbox'?input.checked:input.type==='number'?Number(input.value||0):input.value;}if(globalSection==='connection')s.proxy=data.proxyMode==='direct'?'direct':data.proxyMode==='custom'?data.proxy:'';if(globalSection==='privacy'){s.redactWords=(data.redactWords||'').split('\n').map(x=>x.trim()).filter(Boolean);s.redactRules=[...form.querySelectorAll('.redact-rule-row')].map(row=>({kind:row.querySelector('[data-rule=kind]').value,[row.querySelector('[data-rule=mode]').value]:row.querySelector('[data-rule=value]').value}));}if(globalSection==='telemetry'){const headers={};for(const line of(data['otel-headers']||'').split('\n').filter(x=>x.trim())){const at=line.indexOf('=');if(at<1)throw new Error('Header 使用 名称=值，每行一项');headers[line.slice(0,at).trim()]=line.slice(at+1)||null;}s.otel={enabled:form.querySelector('[name=otel-enabled]').checked,endpoint:data['otel-endpoint'],metrics:form.querySelector('[name=otel-metrics]').checked,bodies:form.querySelector('[name=otel-bodies]').checked,bodiesWhole:form.querySelector('[name=otel-bodiesWhole]').checked,headers};}await api('global/settings',s);const active=form.isConnected&&tab==='settings'&&globalSection===section;if(active)captureGlobalDrafts();clearGlobalFormDraft(form.id,section,saved);if(!active)return;message('设置已保存');await load();}
window.bindBridgeGlobalPage=function(current,epoch){const root=$('#content');groupGlobalFields(root);if(current==='settings')restoreGlobalDrafts();const proxyMode=root.querySelector('[name=proxyMode]'),proxyAddress=root.querySelector('#proxy-address'),proxyInput=root.querySelector('[name=proxy]');if(proxyMode&&proxyAddress&&proxyInput){const update=()=>{proxyAddress.hidden=proxyMode.value!=='custom';proxyInput.required=proxyMode.value==='custom';};proxyMode.addEventListener('change',update);update();}const searchChoice=root.querySelector('[name=searcherChoice]'),searchId=root.querySelector('[name=searcher]');if(searchChoice&&searchId){searchChoice.addEventListener('change',()=>{if(searchChoice.value!=='manual')searchId.value=searchChoice.value;captureGlobalDrafts();});searchId.addEventListener('input',()=>{searchChoice.value=[...searchChoice.options].some(o=>o.value===searchId.value)?searchId.value:'manual';});}const full=root.querySelector('[name=fullContext]'),compact=root.querySelector('[name=compactAt]');if(full&&compact){const update=()=>compact.disabled=full.checked;full.addEventListener('change',update);update();}root.querySelectorAll('#uniform-price-form input[type=number],[name=balanceAlert]').forEach(i=>{i.step='any';i.min='0';});$('#uniform-price-form')?.addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget;runGlobalForm(f,()=>saveUniformPrice(f));});root.querySelectorAll('[data-global-section]').forEach(b=>b.onclick=()=>{captureGlobalDrafts();if(current==='settings')globalSection=b.dataset.globalSection;else usageSection=b.dataset.globalSection;globalRerender().catch(formError);});$('#usage-trend')?.addEventListener('change',e=>{usageTrend=e.target.value;globalRerender().catch(formError);});$('#global-period')?.addEventListener('change',e=>{period=e.target.value;ledgerOffset=0;globalRerender().catch(formError);});$('#route-day')?.addEventListener('change',async e=>{const busy=startButtonBusy(root.querySelector('[data-global=live-routes]'),'查询中');try{const r=await api(`routes/history?day=${encodeURIComponent(e.target.value)}`);if(epoch===renderEpoch)$('#route-records').innerHTML=routeTable(r.routes);}catch(e){message(e.message,true);}finally{busy.finish();}});$('#global-form')?.addEventListener('submit',e=>{e.preventDefault();runGlobalForm(e.currentTarget,()=>globalSave(e.currentTarget));});$('#ledger-filter')?.addEventListener('submit',e=>{e.preventDefault();Object.assign(ledgerFilters,formObject(e.currentTarget),{failed:e.currentTarget.elements.failed.checked});ledgerOffset=0;runGlobalForm(e.currentTarget,globalRerender);});$('#backup-export-form')?.addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget;runGlobalForm(f,async()=>{const d=formObject(f);if(!d.pass)throw new Error('请设置备份加密口令');await downloadResponse(await fetch('/api/backup/export',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({pass:d.pass,keys:f.elements.keys.checked})}),'whalebridge.magpie-backup');message('备份文件已生成');});});$('#backup-import-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget;if(!await ask('恢复备份','所选供应商与设置将按备份内容恢复。当前相同 ID 的供应商将被替换。','恢复'))return;runGlobalForm(f,async()=>{const file=f.elements.file.files[0];if(!file)throw new Error('请选择备份文件');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(file);});await api('backup/import',{data,pass:f.elements.pass.value,providers:f.elements.providers.checked,settings:f.elements.settings.checked});await load();message('备份已恢复');});});$('#sync-form')?.addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget;captureGlobalDrafts();const section=globalSection,saved=(globalDrafts.get(section)||[]).find(d=>d.id===f.id);runGlobalForm(f,async()=>{const data=formObject(f);for(const k of ['pathStyle','keys','usage'])data[k]=f.elements[k].checked;data.autoEvery=Number(data.autoEvery);await api('sync/save',data);await api('sync/auto',{minutes:data.autoEvery});const active=f.isConnected&&tab==='settings'&&globalSection===section;if(active)captureGlobalDrafts();clearGlobalFormDraft(f.id,section,saved);if(!active)return;message('同步已完成');await globalRerender();});});root.querySelectorAll('[data-global]').forEach(b=>b.onclick=()=>globalAction(b).catch(e=>message(e.message,true)));if(current==='usage'&&usageSection==='quotas')loadQuotas(epoch).catch(e=>message(e.message,true));};
async function runGlobalForm(form,work){const buttons=[...form.querySelectorAll('button')].map(b=>[b,b.disabled]),submit=form.querySelector('button[type=submit]'),label=({'backup-export-form':'导出中','backup-import-form':'恢复中','sync-form':'同步中','ledger-filter':'查询中'})[form.id]||'保存中',busy=startButtonBusy(submit,label);buttons.forEach(([b])=>b.disabled=true);form.setAttribute('aria-busy','true');try{await work();}catch(e){message(e.message,true);}finally{busy.finish();buttons.forEach(([b,disabled])=>b.disabled=disabled);form.setAttribute('aria-busy','false');}}
async function globalAction(b){const a=b.dataset.global,id=b.dataset.id;let busy;const waiting={'view-archive':'加载中','copy-search':'读取中','ledger-prev':'查询中','ledger-next':'查询中','live-routes':'查询中','show-route':'加载中','show-search':'读取中'};if(waiting[a])busy=startButtonBusy(b,waiting[a]);b.disabled=true;try{if(a==='view-archive'){const response=await fetch('/api/archive/file?name='+encodeURIComponent(id));if(!response.ok)throw new Error(await response.text());const data=await response.json(),request=data.request||data.Request||{},reply=data.response||data.Response||{};editor={type:'read-only'};$('#editor-title').textContent='供应商请求归档';$('#fields').innerHTML='<section class="panel"><h3>请求 · '+escape(request.method||request.Method||'')+' '+escape(request.path||request.Path||'')+'</h3><pre>'+escape(JSON.stringify(request.headers||request.Headers||{},null,2))+'</pre><pre>'+escape(request.body||request.Body||'')+'</pre><h3>响应 · '+escape(reply.status||reply.Status||'')+'</h3><pre>'+escape(JSON.stringify(reply.headers||reply.Headers||{},null,2))+'</pre><pre>'+escape(reply.body||reply.Body||'')+'</pre>'+((request.truncated||reply.truncated)?'<p class="inline-error">此归档达到单份体积限制，正文已截断；下载内容同样是已保存的片段。</p>':'')+'</section>';showEditor();$('#save').hidden=true;return;}if(a==='copy-search'){const data=await api('search/key?vendor='+encodeURIComponent(id));await navigator.clipboard.writeText(data.key);message('密钥已复制');return;}if(a==='add-uniform-tier'){$('#uniform-price-tiers').insertAdjacentHTML('beforeend',priceTierFields().replaceAll('data-action="remove-price-tier"','data-global="remove-uniform-tier"'));$('#uniform-price-tiers').lastElementChild.querySelector('[data-global]').onclick=e=>e.currentTarget.closest('.price-tier').remove();return;}if(a==='remove-uniform-tier'){b.closest('.price-tier').remove();return;}if(a==='edit-price'){const p=globalData.modelPrices[id]||{};$('#uniform-price-form').elements.model.value=id.slice(2);for(const key of ['input','output','cache_read','cache_write','cache_write_1h'])$('#uniform-price-form').elements[key].value=p[key]??'';$('#uniform-price-tiers').innerHTML=(p.tiers||[]).map(t=>priceTierFields(t).replaceAll('data-action="remove-price-tier"','data-global="remove-uniform-tier"')).join('');$('#uniform-price-tiers').querySelectorAll('[data-global]').forEach(b=>b.onclick=()=>b.closest('.price-tier').remove());return;}if(a==='remove-price'){if(await ask('恢复模型价格','移除统一价格覆盖，按供应商和模型官方价格估算。','恢复')){busy=startButtonBusy(b,'恢复中');await api('model-price',{id,price:null});await globalRerender();}return;}if(a==='cancel-settings'){globalDrafts.delete(globalSection);await globalRerender();return;}if(a==='add-rule'){$('#redact-rules').insertAdjacentHTML('beforeend',ruleRow());$('#redact-rules').lastElementChild.querySelector('[data-global]').onclick=e=>e.currentTarget.closest('.redact-rule-row').remove();return;}if(a==='remove-rule'){b.closest('.redact-rule-row').remove();return;}if(a==='ledger-prev'||a==='ledger-next'){ledgerOffset=Math.max(0,ledgerOffset+(a==='ledger-prev'?-50:50));await globalRerender();return;}if(a==='live-routes'){$('#route-records').innerHTML=routeTable((await api('routes')).routes);return;}if(a==='show-route'){const r=await api('routes/history?day='+encodeURIComponent(b.dataset.day||ledgerFilters.day||''));const rows=r.routes?.filter(x=>String(x.id)===String(id));editor={type:'read-only'};$('#editor-title').textContent='请求路由记录';$('#fields').innerHTML=routeTable(rows);showEditor();$('#save').hidden=true;return;}if(a==='show-search'){const r=await api('search/key?vendor='+encodeURIComponent(id));editor={type:'read-only'};$('#editor-title').textContent='搜索 API 密钥';$('#fields').innerHTML=field('revealed-search','密钥',r.key);showEditor();$('#save').hidden=true;return;}if(a==='remove-search'){if(await ask('移除搜索 API','移除后将不再使用此搜索 API，已有模型搜索能力保留。','移除')){busy=startButtonBusy(b,'移除中');await api('search/delete',{vendor:id});await globalRerender();}return;}if(a==='edit-search'){const old=globalData.searches.find(x=>x.vendor===id)||{};$('#search-editor').hidden=false;$('#search-editor').innerHTML=`<form id="search-edit-form"><h3>${escape(id)}</h3><div class="form-grid">${field('url','服务地址',old.url||'','text',id==='searxng'?'必填，自建 SearXNG 地址':'留空使用官方地址')+field('key','API 密钥','','password',old.keySet?'留空保留已保存密钥':'填写密钥')}</div><div class="actions-bar"><button type="submit" class="primary">保存搜索服务</button><button type="button" id="close-search-edit">取消</button></div></form>`;groupGlobalFields($('#search-editor'));$('#close-search-edit').onclick=()=>$('#search-editor').hidden=true;$('#search-edit-form').onsubmit=e=>{e.preventDefault();const f=e.currentTarget;runGlobalForm(f,async()=>{await api('search/save',{vendor:id,...formObject(f)});await globalRerender();message('搜索服务已保存');});};$('#search-editor').scrollIntoView({block:'nearest'});return;}if(a.startsWith('sync-')){const action=a.slice(5);if(['restore','undo','off'].includes(action)&&!await ask('同步操作',({restore:'使用服务器上的供应商与设置覆盖本机配置，覆盖前会保留加密备份。',undo:'恢复最近一次同步恢复前的本机配置。',off:'关闭自动同步。当前本机配置和服务器备份保留。'})[action],'继续'))return;busy=startButtonBusy(b,action==='restore'||action==='undo'?'恢复中':'同步中');await api('sync/'+action,{});await globalRerender();message('同步操作已完成');}}finally{busy?.finish();if(b.getAttribute('aria-busy')!=='true')b.disabled=false;}}

function uniformPricePanel(){const rows=Object.entries(globalData.modelPrices||{}).filter(([id])=>id.startsWith('*/'));return '<section class="panel global-form-panel">'+sectionHead('跨供应商统一模型价格','用于同一模型从不同供应商产生的费用估算。供应商单独覆盖优先。单位为 USD / 百万 Token。')+ (rows.length?'<div class="table-wrap"><table><thead><tr><th>模型</th><th>输入 / 输出</th><th>缓存读 / 写</th><th>操作</th></tr></thead><tbody>'+rows.map(([id,p])=>'<tr><td>'+escape(id.slice(2))+'</td><td>'+p.input+' / '+p.output+'</td><td>'+p.cache_read+' / '+p.cache_write+'</td><td><button type="button" data-global="edit-price" data-id="'+escape(id)+'">编辑</button><button type="button" data-global="remove-price" data-id="'+escape(id)+'">恢复官方值</button></td></tr>').join('')+'</tbody></table></div>':'')+'<form id="uniform-price-form"><div class="form-grid">'+field('model','模型 ID','','text','例如 deepseek-v4.1-flash')+[['input','输入'],['output','输出'],['cache_read','缓存读取'],['cache_write','缓存写入'],['cache_write_1h','一小时缓存写入（可选）']].map(([k,l])=>field(k,l,'','number','0 表示免费')).join('')+'</div><details class="advanced"><summary>长上下文价格档位</summary><div id="uniform-price-tiers"></div><button type="button" data-global="add-uniform-tier">添加档位</button></details><div class="actions-bar"><button type="submit">保存统一价格</button></div></form></section>';}
async function saveUniformPrice(form){captureGlobalDrafts();const section=globalSection,saved=(globalDrafts.get(section)||[]).find(d=>d.id===form.id),d=formObject(form),price={};for(const k of ['input','output','cache_read','cache_write']){if(d[k]===''||!Number.isFinite(Number(d[k]))||Number(d[k])<0)throw new Error('请填写输入、输出、缓存读写价格；免费请明确填写 0');price[k]=Number(d[k]);}if(d.cache_write_1h!=='')price.cache_write_1h=Number(d.cache_write_1h);price.tiers=[...form.querySelectorAll('.price-tier')].map(row=>{const tier={above:Number(row.querySelector('[data-tier-above]').value)};for(const input of row.querySelectorAll('[data-tier-price]')){if(input.dataset.tierPrice==='cache_write_1h'&&input.value==='')continue;if(input.value===''||!Number.isFinite(Number(input.value))||Number(input.value)<0)throw new Error('请填写档位各项价格，免费请填写 0');tier[input.dataset.tierPrice]=Number(input.value);}return tier;}).sort((a,b)=>a.above-b.above);const model=d.model.trim();const id=model.startsWith('*/')?model:'*/'+model;if(id==='*/')throw new Error('请填写模型 ID');await api('model-price',{id,price});const active=form.isConnected&&tab==='settings'&&globalSection===section;if(active)captureGlobalDrafts();clearGlobalFormDraft(form.id,section,saved);if(!active)return;await globalRerender();message('统一价格已保存');}
